AssistantMessageToolRequest(name='create', tool_call_id='tooluse_swojZ2idY6cyaXu5epY69A', arguments={'file_text': '* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: linear-gradient(135deg, #0f0f1e 0%, #1a1a2e 100%);
  color: #e0e0e0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

main {
  width: 100%;
  max-width: 500px;
}

h1 {
  font-size: 28px;
  font-weight: 600;
  margin-bottom: 32px;
  color: #ffffff;
  letter-spacing: -0.5px;
}

form {
  background: #16213e;
  border: 1px solid #2a3f5f;
  border-radius: 12px;
  padding: 32px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
}

.form-field {
  margin-bottom: 28px;
}

/* Checkbox styling */
input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin-right: 12px;
  margin-top: 2px;
  cursor: pointer;
  vertical-align: top;
  accent-color: #4a9eff;
  flex-shrink: 0;
}

input[type="checkbox"]:focus-visible {
  outline: 3px solid #4a9eff;
  outline-offset: 2px;
  border-radius: 2px;
}

input[type="checkbox"]:checked {
  background-color: #4a9eff;
}

input[type="checkbox"]:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

label {
  display: flex;
  align-items: flex-start;
  cursor: pointer;
  user-select: none;
  color: #e0e0e0;
  font-size: 16px;
  line-height: 1.5;
}

label a {
  color: #4a9eff;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: color 0.2s ease;
}

label a:hover,
label a:focus-visible {
  color: #66b3ff;
}

label a:focus-visible {
  outline: 2px solid #4a9eff;
  outline-offset: 2px;
  border-radius: 2px;
}

.required-indicator {
  color: #ff6b6b;
  margin-left: 4px;
}

.help-text {
  font-size: 14px;
  color: #a0a0a0;
  margin-top: 8px;
  margin-left: 32px;
  line-height: 1.5;
}

.error-text {
  font-size: 14px;
  color: #ff6b6b;
  margin-top: 8px;
  margin-left: 32px;
  line-height: 1.5;
}

input[type="checkbox"]:invalid ~ .error-text {
  display: block;
}

/* Button styling */
.submit-button {
  width: 100%;
  padding: 12px 24px;
  background: linear-gradient(135deg, #4a9eff 0%, #357abd 100%);
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  letter-spacing: 0.3px;
  text-transform: uppercase;
  box-shadow: 0 4px 15px rgba(74, 158, 255, 0.3);
}

.submit-button:hover {
  background: linear-gradient(135deg, #66b3ff 0%, #4a94e8 100%);
  box-shadow: 0 6px 25px rgba(74, 158, 255, 0.4);
  transform: translateY(-2px);
}

.submit-button:focus-visible {
  outline: 3px solid #4a9eff;
  outline-offset: 2px;
  box-shadow: 0 4px 15px rgba(74, 158, 255, 0.3);
}

.submit-button:active {
  transform: translateY(0);
}

.submit-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

/* Responsive */
@media (max-width: 600px) {
  form {
    padding: 24px;
  }

  h1 {
    font-size: 24px;
    margin-bottom: 24px;
  }

  .form-field {
    margin-bottom: 24px;
  }
}

/* High contrast mode */
@media (prefers-contrast: more) {
  input[type="checkbox"]:focus-visible {
    outline-width: 4px;
  }

  .submit-button:focus-visible {
    outline-width: 4px;
  }

  label a:focus-visible {
    outline-width: 3px;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Forced colors mode */
@media (forced-colors: active) {
  form {
    border: 2px solid CanvasText;
  }

  input[type="checkbox"]:focus-visible {
    outline: 3px solid Highlight;
  }

  .submit-button:focus-visible {
    outline: 3px solid Highlight;
  }

  label a {
    color: LinkText;
  }

  label a:visited {
    color: VisitedText;
  }
}
